export function ask(message){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='confirm-dialog';dialog.setAttribute('aria-labelledby','confirmation-title');dialog.innerHTML='<h2 id="confirmation-title">Confirm change</h2><p class="confirmation-message"></p><div class="tool-controls"><button data-answer="cancel">Cancel</button><button data-answer="confirm">Confirm</button></div>';dialog.querySelector('p').textContent=message;const finish=answer=>{dialog.close();dialog.remove();resolve(answer)};dialog.querySelector('[data-answer="cancel"]').onclick=()=>finish(false);dialog.querySelector('[data-answer="confirm"]').onclick=()=>finish(true);dialog.oncancel=e=>{e.preventDefault();finish(false)};document.body.append(dialog);dialog.showModal();dialog.querySelector('[data-answer="cancel"]').focus()})}
